  const powerHelp={soupSlowdown:'Slows falling food for 4 seconds. One charge; use before a crowded wave.',ingredientMagnet:'Pulls nearby food toward the bowl for 4.5 seconds. Does not attract chili bombs.',wokSweep:'Clears chili bombs currently on screen. Save it for a dangerous cluster.',peekPair:'Shows the whole unmatched card board briefly. Use before flipping a tricky pair.',shuffleCards:'Remixes only unmatched cards. Matched pairs stay safe.',secondChance:'Restores one heart, up to the 3-heart limit.',turboBrake:'Slows traffic for 4 seconds so lane changes are easier.',flavorMagnet:'Collects nearby flavor tokens across lanes for 5 seconds; trucks remain dangerous.',laneShield:'Blocks one truck collision. It does not collect tokens for you.',lanternHint:'Briefly lights the next route tile; it does not tap the tile for you.',routePreview:'Shows the numbered route again for a short study window.',extraTime:'Adds 5 seconds to this route only.',focus:'Slows the timing needle for 4 seconds.',wideWindow:'Makes the golden target wider for 5 seconds.',wingFlap:'Gives one stronger flap. It does not make the bird invulnerable.',skyShield:'Blocks one collision with a gate or the ground.',gustClear:'Removes only the next gate, leaving the later gates in place.',snackMagnet:'Pulls nearby dumplings toward the snake for 7 seconds.',snakeSlow:'Slows the snake for 6 seconds to give you more steering time.',snakeShield:'Protects against one wall or tail collision.',paddleExtend:'Widens the paddle for 8 seconds. A missed ball still costs a heart.',ballSlow:'Slows the ball for 6 seconds without changing its path.',creamJump:'Recharge your midair double jump and spring over the next gap.',caramelShield:'Blocks one rolling-pin hit or fall reset.',sprinkleMagnet:'Pulls nearby toppings toward you for 8 seconds.',sesameSlow:'Slows the moving mooncake layer for 5 seconds.',extraDough:'Adds width to the current layer for an easier landing.',goldenTray:'Catches one badly lined-up layer so your tower can continue.'};
