  const powerGuide={noodle:'Soup Slowdown briefly slows all falling items. Ingredient Magnet pulls food toward your bowl. Wok Sweep clears every chili bomb currently on screen. New powers unlock at Levels 4 and 7.',match:'Kitchen Peek reveals the whole board for a moment. Fresh Shuffle remixes unmatched cards. Second Chance restores a heart. New powers unlock at Levels 4 and 7.',roadster:'Turbo Brake slows traffic. Flavor Magnet collects tokens from any lane. Lane Shield blocks a crash. New powers unlock at Levels 4 and 7.',trailblazer:'Lantern Hint shows your next tile. Route Preview briefly replays the route. Extra Time adds seconds to the current timer. New powers unlock at Levels 4 and 7.',ace:'Focus slows the chopsticks. Wide Window temporarily enlarges the target. Second Chance restores a heart. New powers unlock at Levels 4 and 7.',wok:'Wing Boost gives a stronger flap. Sky Shield absorbs one collision. Gate Gust clears the next gate. New powers unlock at Levels 4 and 7.',lantern:'Dumpling Magnet pulls nearby food toward your snake. Slow Slither gives you time to steer across the open platform. Tail Shield protects you from one crash. New powers unlock at Levels 4 and 7.',teatoss:'Paddle Extend widens your paddle. Slow Ball briefly slows the ball. Extra Heart restores one life. Some blocks drop a glowing extra charge when shattered; catch it with the paddle. New powers unlock at Levels 4 and 7.',sugar:'Whipped Cream recharges one midair jump. Caramel Shield absorbs one collision. Sprinkle Magnet pulls nearby toppings toward you. New powers unlock at Levels 4 and 7.',mooncake:'Sesame Slowdown gives you more time to line up each layer. Extra Dough widens your current layer. Golden Tray safely catches one badly lined-up drop. New powers unlock at Levels 4 and 7.'};
  const assetRoot='/assets/forbidden_bite/',sceneFiles={noodle:'arcade-noodle-mountain.webp',match:'arcade-dish-garden.webp',roadster:'arcade-roadster-food-market.jpg',trailblazer:'arcade-trail-garden.webp',ace:'arcade-ace-dim-sum.jpg',wok:'arcade-city-chongqing-night.jpg',lantern:'arcade-city-shanghai-park.jpg',teatoss:'arcade-city-street.jpg',sugar:'arcade-sugar-rooftops-ai.webp',mooncake:'arcade-sugar-rooftops-ai.webp'};
  const loadArt=file=>{const image=new Image();image.src=assetRoot+file;image.addEventListener('load',()=>{if(!state)drawAttract()},{once:true});return image};
  const sceneImages={},bossNames={noodle:['Red Pepper Wyrm','Mooncake Mimic','Bamboo Colossus','Lantern Phoenix','Dumpling Emperor'],match:['Mooncake Mimic','Golden Glider','Crystal Crimper','Jade Feast Beast','Royal Dumpling'],roadster:['Lantern Phoenix','Turbo Tangbao','Red Pepper Wyrm','Golden Glider','Storm Bao'],trailblazer:['Bamboo Colossus','Jade Feast Beast','Mooncake Mimic','Crystal Crimper','Noodle Golem'],ace:['Dumpling Emperor','Crystal Crimper','Lantern Phoenix','Storm Bao','Forbidden Champion'],wok:['Pepper Wing','Chili Kite','Sky Wok Dragon','Storm Sparrow','The Great Flapper'],lantern:['Noodle Cobra','Jade Serpent','Dumpling Python','Garden Dragon','The Long Slither'],teatoss:['Brick Bao','Tea Tower','Golden Wall','Jade Breaker','The Grand Stack'],sugar:['Gingerbread Guardian','The Rolling Pin','Macaron Mech','Frosting Dragon','The Great Cake'],mooncake:['Sesame Sentinel','The Jade Rabbit','Moonlight Molder','Golden Crust Dragon','The Emperor Cake']},bossSpriteByMode={noodle:2,match:1,roadster:4,trailblazer:3,ace:0,wok:2,lantern:3,teatoss:1,sugar:4,mooncake:1},dishSpriteByEmoji={'🍜':0,'🥟':1,'🍗':2,'🍤':3,'🥢':4,'🍵':5,'🥒':6,'🍚':7};
  let bossAtlas=null,foodSprites=[],dishSprites=[],vehicleSprites=[],noodleBowlSprite=null;
  function ensureModeAssets(next){if(!sceneImages[next]&&next!=='lantern'&&next!=='sugar'&&sceneFiles[next])sceneImages[next]=loadArt(sceneFiles[next]);if(next==='noodle'&&!noodleBowlSprite)noodleBowlSprite=loadArt('arcade-noodle-bowl-ai.png');if((next==='noodle'||next==='wok')&&!foodSprites.length)foodSprites=['arcade-food-noodles.webp','arcade-food-bok-choy.webp','arcade-food-chicken.webp','arcade-food-carrot.webp','arcade-food-mushroom.webp','arcade-food-chili.webp'].map(loadArt);if((next==='match'||next==='trailblazer'||next==='lantern')&&!dishSprites.length)dishSprites=Array.from({length:16},(_,index)=>loadArt(`arcade-dish-${String(index+1).padStart(2,'0')}.webp`));if(next==='roadster'&&!vehicleSprites.length){vehicleSprites=['arcade-racer-jade-lite.webp','arcade-racer-red-lite.webp','arcade-truck-gold-lite.webp','arcade-truck-cream-lite.webp'].map(loadArt)}}
  const bestKey='forbidden-bite-avatar-arcade-best-v1';
  const bestLevelKey='forbidden-bite-avatar-arcade-best-level-v1';
  const progressKey='forbidden-bite-avatar-arcade-progress-v1';
  const badgeKey='forbidden-bite-arcade-badges-v1',dailyKey='forbidden-bite-arcade-daily-v1';
  let best=safeBest(),bestLevel=safeStore(bestLevelKey),progress=safeProgress(),badges=safeStore(badgeKey),dailyDone=safeStore(dailyKey),mode='noodle',state=null,lastFrame=0,keys=new Set(),pointerStart=null,runToken=0,selectedPower={};
  function safeBest(){try{return JSON.parse(localStorage.getItem(bestKey)||'{}')||{}}catch{return {}}}
  function safeProgress(){try{return JSON.parse(localStorage.getItem(progressKey)||'{}')||{}}catch{return {}}}
  function safeStore(key){try{return JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{return {}}}
  function saveBest(){try{localStorage.setItem(bestKey,JSON.stringify(best))}catch{}}
  function saveBestLevel(){try{localStorage.setItem(bestLevelKey,JSON.stringify(bestLevel))}catch{}}
  function saveProgress(){try{localStorage.setItem(progressKey,JSON.stringify(progress))}catch{}}
  function saveStore(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
  function todayKey(){const d=new Date();return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function dailyLevel(id=mode){let n=Array.from(todayKey()+id).reduce((a,c)=>((a*31)+c.charCodeAt(0))>>>0,7);return n%100+1}
  function nextLevel(){return Math.min(100,Math.max(1,Number(progress[mode])||1))}
  function syncModeBadges(){document.querySelectorAll('.mode-card').forEach(btn=>{const badge=btn.querySelector('.difficulty');if(badge)badge.textContent='LEVEL '+Math.min(100,Math.max(1,Number(progress[btn.dataset.mode])||1))+'/100'})}
  function missionCounts(){if(!state)return null;const s=state;if(mode==='noodle')return['FOOD CAUGHT',s.need,s.goal];if(mode==='match')return['DISH PAIRS',s.matched.size/2,s.pairs];if(mode==='roadster')return['TOKENS COLLECTED',s.tokens,s.goalTokens];if(mode==='trailblazer')return['ROUTE STEPS',s.step,s.route.length];if(mode==='ace')return['TIMING HITS',s.hits,s.goalHits];if(mode==='wok')return['GATES CLEARED',s.gates,s.gateGoal];if(mode==='lantern')return s.snakeGateOpen?['EXIT GATE OPEN · FIND IT',0,1]:['DUMPLINGS TO OPEN GATE',s.snakeCollected,s.snakeGoal];if(mode==='sugar')return['TOPPINGS COLLECTED',s.sugarCollected,s.sugarGoal];if(mode==='mooncake')return['MOONCAKE LAYERS',s.stackLayers.length-1,s.stackGoal];return['TEA BRICKS BROKEN',s.bricks.length-s.bricksLeft,s.bricks.length]}
  function syncMissionMeter(){const meter=$('mission-meter'),label=$('mission-label'),value=$('mission-value'),fill=$('mission-fill');if(!meter||!label||!value||!fill)return;const counts=missionCounts();if(!counts){label.textContent='NEXT LEVEL TARGET';value.textContent='Start a round to see your goal';fill.style.width='0%';meter.setAttribute('aria-valuemax','1');meter.setAttribute('aria-valuenow','0');return}const[title,done,total]=counts,progressNow=Math.max(0,Math.min(total,done));label.textContent=title;value.textContent=`${progressNow}/${total}`;fill.style.width=`${total?progressNow/total*100:0}%`;meter.setAttribute('aria-label',`${title.toLowerCase()}: ${progressNow} of ${total}`);meter.setAttribute('aria-valuemax',String(total));meter.setAttribute('aria-valuenow',String(progressNow))}
  function renderRecords(){const host=$('record-grid');host.replaceChildren();for(const id of Object.keys(titles)){const chip=document.createElement('div');chip.className='record-chip';const label=document.createElement('span');label.textContent=titles[id].toUpperCase();const value=document.createElement('strong');value.textContent=best[id]?String(best[id]):'No score yet';const level=document.createElement('small');level.className='record-level';level.textContent=bestLevel[id]?`Best clear: Level ${bestLevel[id]}`:'Levels cleared: 0';chip.append(label,value,level);host.append(chip)}}
  function recordBestLevel(level){if(level>(Number(bestLevel[mode])||0)){bestLevel[mode]=level;saveBestLevel();renderRecords()}}
  function renderPictureTutorial(){const host=$('picture-tutorials');if(!host)return;const[asset,column]=tutorialArtwork[mode];host.replaceChildren(...pictureTutorials[mode].map((label,index)=>{const card=document.createElement('div');card.className='picture-step';card.setAttribute('aria-label',`Step ${index+1}: ${label}`);const image=document.createElement('div');image.className='picture-step-art';image.setAttribute('role','img');image.setAttribute('aria-label',`${titles[mode]} gameplay illustration: ${label}.`);if(mode==='sugar'||mode==='mooncake'){image.classList.add('sugar-tutorial-art');image.style.backgroundImage='linear-gradient(140deg,#f6d46b,#f3a55d 52%,#4c9b59)';image.textContent=mode==='sugar'?['🏃‍♀️　🍰','🍩　⬆️　🪵','🍓　🏁　🚪'][index]:['🥮　↔️','🥮　⬇️　🥮','🏆　🥮　✨'][index]}else{image.style.backgroundImage=`url('/assets/forbidden_bite/${asset}')`;if(mode==='lantern'){image.style.backgroundSize='150% auto';image.style.backgroundPosition=`${index===0?'0%':index===1?'50%':'100%'} 50%`}else{image.style.backgroundPosition=`${column} ${index===0?'0%':index===1?'16.7%':'33.3%'}`;if(mode==='roadster'||mode==='trailblazer'||mode==='teatoss')image.style.backgroundPosition=`${column} ${index===0?'66.7%':index===1?'83.3%':'100%'}`}}const caption=document.createElement('span');caption.className='picture-step-label';caption.innerHTML=`<span class="tutorial-number">${index+1}</span>${label}`;card.append(image,caption);return card}))}
  const badgeDefs=[['first','🥢','First clear'],['boss','👑','Boss beaten'],['daily','🌞','Daily challenge']];
  function awardBadge(id,type){badges[id]??=[];if(!badges[id].includes(type)){badges[id].push(type);saveStore(badgeKey,badges);renderBadges()}}
  function renderBadges(){const host=$('badge-list');if(!host)return;host.replaceChildren(...badgeDefs.map(([type,icon,label])=>{const chip=document.createElement('span');const earned=(badges[mode]||[]).includes(type);chip.className='badge-chip'+(earned?' is-earned':'');chip.textContent=`${icon} ${label}${earned?' · earned':' · locked'}`;chip.title=type==='first'?'Clear any level in this game':type==='boss'?'Clear a boss level in this game':'Complete this game’s daily challenge';return chip}))}
  function refreshDailyButton(){const b=$('daily-challenge');if(!b)return;const done=dailyDone[`${todayKey()}:${mode}`];b.textContent=done?`Daily cleared · Level ${dailyLevel()}`:`Daily challenge · Level ${dailyLevel()}`;b.title=`One special ${titles[mode]} level picked for today. Resets tomorrow.`}


  const arcadeStage=document.querySelector('.arcade-stage'),exitFullscreenButton=$('exit-fullscreen'),exitGameButton=$('exit-game');
  function leaveFullscreen(){document.body.classList.remove('is-game-fullscreen');exitFullscreenButton.hidden=true;exitGameButton.hidden=true;if(state?.live){state.live=false;state.awaitingNext=true;runToken++;$('start-game').textContent=`Continue Level ${state.level}`;$('overlay-title').textContent='Paused at the same level';$('overlay-copy').textContent=`Your progress is saved. Continue Level ${state.level} when you are ready, or Restart 100 levels to begin again.`;overlay.hidden=false;statusEl.textContent='Game paused. Your current level is saved on this device.'}if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{});requestAnimationFrame(resize)}
  function exitGame(){runToken++;keys.clear();if(state)state.live=false;document.body.classList.remove('is-game-fullscreen');exitFullscreenButton.hidden=true;exitGameButton.hidden=true;if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{});state=null;overlay.hidden=false;$('overlay-title').textContent='Back to the arcade';$('overlay-copy').textContent='Your run has ended. Pick another game above or continue this one when you’re ready.';$('start-game').textContent=`Play ${titles[mode]} · Level ${nextLevel()}`;statusEl.textContent='Game exited. Choose another game or start again.';requestAnimationFrame(()=>{resize();document.getElementById('mode-grid').scrollIntoView({behavior:'smooth',block:'start'})})}
