  function awardPowerCharges(s,first=false){for(const power of powerDefs[mode])if(power.unlock<=s.level){if(s.powerCharges[power.id]===undefined)s.powerCharges[power.id]=1;else if(!first)s.powerCharges[power.id]=Math.min(3,s.powerCharges[power.id]+1)}}
  function levelGoalText(){if(!state)return'';if(mode==='noodle')return`catch ${state.goal} foods and avoid chili bombs`;if(mode==='match')return`match ${state.pairs} dish pairs · ${state.maxMoves-state.moves} moves left`;if(mode==='roadster')return`collect ${state.goalTokens} tokens in ${state.goalTime.toFixed(1)} seconds`;if(mode==='trailblazer')return`remember ${state.route.length} tiles · ${state.routeTime.toFixed(1)} seconds`;if(mode==='wok')return`pass ${state.gateGoal} lantern gates`;if(mode==='lantern')return state.snakeGateOpen?'guide the snake through the open exit gate':`collect ${state.snakeGoal} dumplings to open the exit gate`;if(mode==='sugar')return`collect ${state.sugarGoal} toppings and reach the bakery gate`;if(mode==='mooncake')return`stack ${state.stackGoal} layers without dropping the filling`;if(mode==='teatoss')return`break ${state.bricksLeft} remaining blocks`;return`land ${state.goalHits} precise hits`}
