  function burst(x,y,color,count=14){if(!state)return;for(let i=0;i<count;i++){const angle=Math.random()*Math.PI*2,speed=40+Math.random()*220,life=.28+Math.random()*.55;state.parts.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life,maxLife:life,size:2+Math.random()*4,color})}}
