  function tapEffect(x,y,color='#ffe17b'){if(!state?.live)return;state.ripples.push({x,y,color,age:0});burst(x,y,color,8)}
  function updateParticles(dt){for(const p of state.parts){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=90*dt;p.vx*=.985;p.life-=dt}state.parts=state.parts.filter(p=>p.life>0);for(const r of state.ripples)r.age+=dt;state.ripples=state.ripples.filter(r=>r.age<.48)}
