  function dropMooncake(){const s=state;if(!s?.live||mode!=='mooncake'||s.layerDropFlash>0)return;const moving=s.layer,below=s.stackLayers[s.stackLayers.length-1],left=Math.max(moving.x,below.x),right=Math.min(moving.x+moving.w,below.x+below.w),overlap=right-left;let landedX=left,landedW=overlap;if(overlap<28){if(s.stackAssist){s.stackAssist=false;landedX=below.x;landedW=below.w;statusEl.textContent='Golden Tray caught the layer and centered it safely.'}else{hurt('Layer missed! Tap when the mooncake overlaps the stack.');if(s.live){s.layer={x:below.x,w:below.w,y:below.y-24};s.layerDir=Math.random()<.5?-1:1}return}}else if(overlap<moving.w*.38){hurt('Too much overhang! Your stack wobbled, but the tower survived.');if(!s.live)return}const top={x:landedX,w:landedW,y:below.y-24};s.stackLayers.push(top);s.stackDrops++;awardSkillScore(Math.round(115+landedW*.3));burst(landedX+landedW/2,top.y,'#f4d36c',14);soundEffect('pickup');s.layerDropFlash=.16;if(s.stackLayers.length-1>=s.stackGoal){clearLevel(`You stacked ${s.stackGoal} mooncake layers into a steady tower.`);return}const nextWidth=landedW,center=landedX+landedW/2;s.layer={x:center-nextWidth/2,w:nextWidth,y:top.y-24};s.layerDir=Math.random()<.5?-1:1;if(s.stackLayers.length>9){const shift=s.stackLayers.length-9;for(const item of s.stackLayers)item.y+=shift*24;s.layer.y+=shift*24;s.stackLift=(s.stackLift||0)+shift*24}else s.stackLift=0;statusEl.textContent=`Layer ${s.stackLayers.length-1}/${s.stackGoal} · ${Math.round(landedW)} px wide. ${s.boss?'Boss tower! ':''}Keep stacking.`;syncHud()}
  function spawnSnakeFood(s){let cell;do{cell={x:Math.floor(Math.random()*s.snakeCols),y:Math.floor(Math.random()*s.snakeRows)}}while(s.snake.some(segment=>segment.x===cell.x&&segment.y===cell.y)||cell.x===s.snakeGate.x&&cell.y===s.snakeGate.y);return cell}
  function spawnSnakeCoin(s){let cell;do{cell={x:Math.floor(Math.random()*s.snakeCols),y:Math.floor(Math.random()*s.snakeRows)}}while(s.snake.some(segment=>segment.x===cell.x&&segment.y===cell.y)||s.snakeFood&&cell.x===s.snakeFood.x&&cell.y===s.snakeFood.y||cell.x===s.snakeGate.x&&cell.y===s.snakeGate.y);return {...cell,ttl:8}}
  let brickTiles={};
  function makeBrickTile(hp){const tile=document.createElement('canvas');tile.width=156;tile.height=56;const g=tile.getContext('2d'),grad=g.createLinearGradient(0,0,0,56);grad.addColorStop(0,hp>1?'#ff9a72':'#9dffe0');grad.addColorStop(.24,hp>1?'#e45c46':'#41c993');grad.addColorStop(1,hp>1?'#922b39':'#167857');g.save();g.shadowColor=hp>1?'#ff775d':'#45f0bd';g.shadowBlur=10;g.fillStyle=grad;g.beginPath();g.roundRect(3,4,150,48,14);g.fill();g.restore();g.strokeStyle=hp>1?'#ffe2a9':'#d5ffe9';g.lineWidth=2;g.beginPath();g.roundRect(5,5,146,45,12);g.stroke();g.strokeStyle='#ffffff58';g.lineWidth=2;g.beginPath();g.moveTo(16,11);g.lineTo(140,11);g.stroke();g.fillStyle=hp>1?'#ffcd82':'#a5ffda';g.beginPath();g.roundRect(66,17,24,21,7);g.fill();g.fillStyle=hp>1?'#983e43':'#14735a';g.beginPath();g.arc(78,27.5,5.5,0,Math.PI*2);g.fill();g.fillStyle='#fff2c0';g.beginPath();g.arc(78,27.5,2.2,0,Math.PI*2);g.fill();g.fillStyle='#ffffff32';g.beginPath();g.roundRect(13,17,7,24,3);g.fill();g.beginPath();g.roundRect(136,17,7,24,3);g.fill();return tile}
